[metadata] {"type": "create", "filePath": "/workspace/repo/src/integrations/prefect-kubernetes/prefect_kubernetes/diagnostics.py", "content": """"Structured diagnosis of Kubernetes pod failures.

This module inspects a Kubernetes pod ``status`` dictionary and turns known
failure conditions (image pull errors, OOM kills, crash loops, unschedulable
pods, evictions, ...) into a structured :class:`InfrastructureDiagnosis` that
can be surfaced to users in flow run logs.
"""

from __future__ import annotations

import enum
from dataclasses import dataclass
from typing import Any


class DiagnosisLevel(str, enum.Enum):
    """Severity level for an infrastructure diagnosis."""

    ERROR = "error"
    WARNING = "warning"


@dataclass(frozen=True)
class InfrastructureDiagnosis:
    """A structured diagnosis of a Kubernetes pod failure."""

    level: DiagnosisLevel
    summary: str
    detail: str
    resolution: str


# Container ``waiting`` state reasons that indicate an image could not be pulled.
_IMAGE_PULL_REASONS = frozenset({"ImagePullBackOff", "ErrImagePull"})


def _iter_container_statuses(status: dict[str, Any]) -> list[dict[str, Any]]:
    """Return all container statuses, including init containers."""
    container_statuses: list[dict[str, Any]] = []
    for key in ("initContainerStatuses", "containerStatuses"):
        value = status.get(key)
        if value:
            container_statuses.extend(cs for cs in value if isinstance(cs, dict))
    return container_statuses


def _diagnose_waiting(
    container_name: str, waiting: dict[str, Any]
) -> InfrastructureDiagnosis | None:
    """Diagnose a container's ``waiting`` state, if it is a known failure."""
    reason = waiting.get("reason")
    if reason is None:
        return None

    message = waiting.get("message")

    if reason in _IMAGE_PULL_REASONS:
        detail = f"{reason}: {message}" if message else reason
        return InfrastructureDiagnosis(
            level=DiagnosisLevel.ERROR,
            summary=f"Container {container_name!r} could not pull its image ({reason}).",
            detail=detail,
            resolution=(
                "Verify the image name and tag are correct and that the cluster "
                "has credentials to pull the image from its registry."
            ),
        )

    if reason == "CrashLoopBackOff":
        detail = f"{reason}: {message}" if message else reason
        return InfrastructureDiagnosis(
            level=DiagnosisLevel.ERROR,
            summary=f"Container {container_name!r} is crash-looping ({reason}).",
            detail=detail,
            resolution=(
                "Inspect the container logs for the underlying error and fix the "
                "cause of the repeated crashes."
            ),
        )

    return None


def _diagnose_terminated(
    container_name: str, terminated: dict[str, Any]
) -> InfrastructureDiagnosis | None:
    """Diagnose a container's ``terminated`` state, if it is a known failure."""
    reason = terminated.get("reason")
    if reason is None:
        return None

    message = terminated.get("message")

    if reason == "OOMKilled":
        detail = f"{reason}: {message}" if message else reason
        return InfrastructureDiagnosis(
            level=DiagnosisLevel.ERROR,
            summary=f"Container {container_name!r} was OOMKilled (out of memory).",
            detail=detail,
            resolution=(
                "Increase the memory request/limit for the container or reduce the "
                "memory used by the flow run."
            ),
        )

    if reason == "Evicted":
        detail = f"{reason}: {message}" if message else reason
        return InfrastructureDiagnosis(
            level=DiagnosisLevel.WARNING,
            summary=f"Container {container_name!r} was evicted from its node.",
            detail=detail,
            resolution=(
                "Check node resource pressure and pod resource requests; the "
                "container may need to be scheduled on a node with more capacity."
            ),
        )

    return None


def _diagnose_conditions(
    status: dict[str, Any],
) -> InfrastructureDiagnosis | None:
    """Diagnose pod-level ``conditions``, e.g. an unschedulable pod."""
    conditions = status.get("conditions")
    if not conditions:
        return None

    for condition in conditions:
        if not isinstance(condition, dict):
            continue
        if condition.get("type") != "PodScheduled":
            continue
        if condition.get("reason") != "Unschedulable":
            continue

        message = condition.get("message")
        return InfrastructureDiagnosis(
            level=DiagnosisLevel.WARNING,
            summary="Pod is unschedulable and cannot be placed on a node.",
            detail=message if message else "Pod is unschedulable.",
            resolution=(
                "Check node capacity, resource requests, node selectors, "
                "affinities, taints, and tolerations for the pod."
            ),
        )

    return None


def _diagnose_pod_status(
    status: dict[str, Any],
) -> InfrastructureDiagnosis | None:
    """Diagnose pod-level ``status`` fields, e.g. an evicted pod."""
    if status.get("reason") == "Evicted":
        message = status.get("message")
        return InfrastructureDiagnosis(
            level=DiagnosisLevel.WARNING,
            summary="Pod was evicted from its node.",
            detail=message if message else "Pod was evicted.",
            resolution=(
                "Check node resource pressure and pod resource requests; the pod "
                "may need to be scheduled on a node with more capacity."
            ),
        )

    return None


def diagnose_k8s_pod(status: dict[str, Any]) -> InfrastructureDiagnosis | None:
    """Inspect a pod status dictionary and return a structured diagnosis.

    Returns ``None`` if the pod is healthy or in a state that does not require
    intervention.
    """
    if not status:
        return None

    container_statuses = _iter_container_statuses(status)

    # Waiting-state failures take priority over terminated-state failures, so
    # scan all containers for waiting failures first.
    for container_status in container_statuses:
        waiting = container_status.get("state", {}).get("waiting")
        if not waiting:
            continue
        diagnosis = _diagnose_waiting(
            container_status.get("name", "<unknown>"), waiting
        )
        if diagnosis is not None:
            return diagnosis

    for container_status in container_statuses:
        terminated = container_status.get("state", {}).get("terminated")
        if not terminated:
            continue
        diagnosis = _diagnose_terminated(
            container_status.get("name", "<unknown>"), terminated
        )
        if diagnosis is not None:
            return diagnosis

    if (diagnosis := _diagnose_conditions(status)) is not None:
        return diagnosis

    if (diagnosis := _diagnose_pod_status(status)) is not None:
        return diagnosis

    return None
